{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The managed policy is attached directly to an IAM user, increasing the risk of excessive or retained permissions through decentralized access management. Assigning the policy through a group provides more consistent and auditable permission management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc19-UpdateExistingGlueDevEndpoint-group" {
  name = "privesc19-UpdateExistingGlueDevEndpoint-group"
}

resource "aws_iam_group_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-group-attach-policy" {
  group      = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}

resource "aws_iam_user_group_membership" "privesc19-UpdateExistingGlueDevEndpoint-user-membership" {
  user = aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name

  groups = [
    aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name,
  ]
}
",
  "fix_summary": "Replaced the direct user policy attachment with an IAM group policy attachment and added the existing user to that group."
}
